#include "RemoteRequests.h"
#include "RuntimeContract.h"
// Positive, declarative driver metadata. This does not read hardware or contain
// application policy. The registry and condition engine consume the same model.
static JsonObject propertySpec(JsonObject out,const char*name,const char*type,const char*unit=nullptr,const char*access="r"){
  auto p=out["properties"][name].to<JsonObject>();p["type"]=type;p["access"]=access;if(unit)p["unit"]=unit;return p;
}
static void eventSpecs(JsonObject out,std::initializer_list<const char*> names){auto a=out["events"].to<JsonArray>();for(auto n:names)a.add(n);}
static void batteryProperties(JsonObject out,bool externalSense){
  propertySpec(out,"mv","number","mV");auto p=propertySpec(out,"calibration_gain","number",nullptr,"rw");p["minimum"]=0.8;p["maximum"]=1.2;
  if(externalSense){propertySpec(out,"external_power","boolean");out["constraints"]["voltage_sampling"]="while_external_power_absent";}
  eventSpecs(out,{"sample","changed"});
}
static void batteryDescription(JsonObject out){batteryProperties(out,pins::VBUS_CLAMPS_BATTERY_ADC);}
static void buttonsDescription(JsonObject out){ButtonGestures::describe(out);for(auto n:{"buttons.A.pressed","buttons.B.pressed","buttons.C.pressed"})propertySpec(out,n,"boolean");eventSpecs(out,{"press","release","long_press","repeat","click"});out["configuration_schema"]="/dev/buttons describe";}
static void imuDescription(JsonObject out){for(auto n:{"raw.0","raw.1","raw.2"})propertySpec(out,n,"integer","raw_count");propertySpec(out,"interrupt","boolean");propertySpec(out,"motion","boolean",nullptr,"rw");propertySpec(out,"rotation","integer","degree");eventSpecs(out,{"interrupt","orientation","motion","tap"});}
static void wifiDescription(JsonObject out){propertySpec(out,"enabled","boolean");propertySpec(out,"selection","string");propertySpec(out,"auto_connect","boolean");propertySpec(out,"configuration_pending","boolean");propertySpec(out,"connection_pending","boolean");out["configuration_schema"]="/dev/wifi describe";propertySpec(out,"connected","boolean");propertySpec(out,"ssid","string");propertySpec(out,"ip","string");propertySpec(out,"rssi","number","dBm");auto p=propertySpec(out,"tx_power_dbm","number","dBm","rw");p["minimum"]=2;p["maximum"]=20;propertySpec(out,"power_save","string",nullptr,"rw");eventSpecs(out,{"changed","connected","disconnected","selection_changed","attempt_started","attempt_failed","manual_released","scan_completed","scan_failed","configuration_changed","configuration_applied","configuration_failed"});}
static void usbDescription(JsonObject out){propertySpec(out,"connected","boolean");propertySpec(out,"events","boolean",nullptr,"rw");out["functions"].to<JsonArray>().add("cdc");eventSpecs(out,{"changed"});}
static void micDescription(JsonObject out){out["encodings"]="ima-adpcm";out["packet_max_bytes"]=91;out["session_capacity"]=4;out["read_chunk_semantics"]="peek_until_ack";out["acknowledgement"]="ack.next_sequence or read_chunk.after_sequence";out["buffer_configuration"]="network_buffer_blocks,storage_buffer_blocks";asyncContract(out,"start","/dev/mic",{"stopped","failed"})["recording_id"]="recording_id";propertySpec(out,"recording","boolean");propertySpec(out,"recording_id","string");propertySpec(out,"sample_rate","integer","Hz");propertySpec(out,"buffered_chunks","integer");propertySpec(out,"dropped_samples","integer");propertySpec(out,"storage_pending","boolean");propertySpec(out,"capture_failed","boolean");propertySpec(out,"storage_dropped_samples","integer");eventSpecs(out,{"started","stopped","failed","stored","storage_failed","readable"});}
static void sdDescription(JsonObject out){for(auto m:{"probe","mount","space"})NativeOperation::describe(out,m,"/dev/sd");propertySpec(out,"mounted","boolean");propertySpec(out,"powered","boolean");propertySpec(out,"tuned","boolean");propertySpec(out,"link_ready","boolean");propertySpec(out,"read_only","boolean");propertySpec(out,"filesystem","string");propertySpec(out,"mode","string");propertySpec(out,"active_effective_hz","integer","Hz");propertySpec(out,"card_mode_max_hz","integer","Hz");eventSpecs(out,{"link_ready","link_failed","mounted","volume_unavailable"});}
