static void clockDescription(JsonObject out){propertySpec(out,"monotonic_ms","integer","ms");propertySpec(out,"unix_s","integer","s","rw");propertySpec(out,"cpu_mhz","integer","MHz","rw");}
static void powerDescription(JsonObject out){propertySpec(out,"state","string");propertySpec(out,"cpu_mhz","integer","MHz");propertySpec(out,"wifi_power_save","string");propertySpec(out,"peripherals_powered","boolean");eventSpecs(out,{"sleep_committed","woke","aborted","cut_requested","power_cut_not_achieved"});}
static void conditionDescription(JsonObject out){out["operators"].to<JsonArray>();for(auto n:{"above","below","equal","change"})out["operators"].add(n);out["capacity"]=Conditions::CAPACITY;eventSpecs(out,{"entered","exited","changed"});}

static void httpDescription(JsonObject out){httpAsyncDescription(out);propertySpec(out,"active","boolean");propertySpec(out,"status","integer");propertySpec(out,"transport_ok","boolean");propertySpec(out,"http_ok","boolean");propertySpec(out,"cancel_requested","boolean");eventSpecs(out,{"completed","failed","readable"});}

static void nfsDescription(JsonObject o){propertySpec(o,"running","boolean");propertySpec(o,"state","string");propertySpec(o,"owned_heap_bytes","integer","byte");propertySpec(o,"requests","integer");eventSpecs(o,{"started","stopped","handles_invalidated"});o["protocol"]="NFSv3/TCP";o["library_version"]="ESP32NFS 1.3.0";propertySpec(o,"memory_used_bytes","integer","byte");propertySpec(o,"memory_failures","integer");propertySpec(o,"path_identities","integer");}

static void tcpDescription(JsonObject o){propertySpec(o,"active","boolean");eventSpecs(o,{"accepted","connected","closed","failed","readable"});o["connection_limit"]=4;o["chunk_limit_bytes"]=1024;o["addressing"]="numeric_ipv4";}
static void udpDescription(JsonObject o){propertySpec(o,"open","boolean");eventSpecs(o,{"readable"});o["addressing"]="numeric_ipv4_or_ipv6";o["datagram_limit_bytes"]=1024;}
static void wsNativeDescription(JsonObject);
static void wsDescription(JsonObject o){wsNativeDescription(o);propertySpec(o,"connected","boolean");propertySpec(o,"started","boolean");propertySpec(o,"dropped_messages","integer");eventSpecs(o,{"connected","failed","disconnected","closed","readable","overflow","sent","send_failed"});o["role"]="client";o["message_limit_bytes"]=1024;}
static void httpServerDescription(JsonObject o){propertySpec(o,"active","boolean");eventSpecs(o,{"request"});o["route_limit"]=6;o["request_limit"]=4;o["body_limit_bytes"]=2048;o["dynamic_response"]="accepted_then_respond_and_read";}
static void remoteDescription(JsonObject o){notesos::RemoteRequests::describe(o);propertySpec(o,"pending","boolean");eventSpecs(o,{"queued","completed","failed"});o["queue_capacity"]=4;}
static void bleDescription(JsonObject o){for(auto method:{"start","restart","stop","connect","gatt_read","gatt_write","subscribe"})asyncContract(o,method,"/dev/ble",{"operation_completed","operation_failed"})["operation_id"]="operation_id";asyncContract(o,"scan","/dev/ble",{"scan_completed"})["operation_id"]="operation_id";propertySpec(o,"running","boolean");propertySpec(o,"connections","integer");propertySpec(o,"operation_active","boolean");eventSpecs(o,{"started","stopped","write","connections","operation_completed","operation_failed","notification","overflow","discovered","scan_completed"});o["modes"]="gatt,hid,central";o["value_limit_bytes"]=128;o["hid_report_ids"]="1,2,3,4";}
static void threadDescription(JsonObject o){for(auto method:{"start","stop"})NativeOperation::describe(o,method,"/net/thread");propertySpec(o,"running","boolean");propertySpec(o,"role","string");eventSpecs(o,{"started","stopped"});o["configuration"]="active_dataset_tlvs";}
static void zigbeeDescription(JsonObject o){asyncContract(o,"start","/net/zigbee",{"started","start_failed"})["operation_id"]="operation_id";asyncContract(o,"send","/net/zigbee",{"tx_status"})["operation_id"]="operation_id";propertySpec(o,"connected","boolean");propertySpec(o,"running","boolean");eventSpecs(o,{"started","start_failed","packet","tx_status","overflow"});o["roles"]="router,coordinator";o["transport"]="APS";o["payload_limit_bytes"]=128;}
static void radioDescription(JsonObject o){propertySpec(o,"wifi.connected","boolean");propertySpec(o,"wifi.enabled","boolean");propertySpec(o,"ble.running","boolean");o["wifi_control"]="/dev/wifi";o["ble_control"]="/dev/ble";propertySpec(o,"active_protocol","string");propertySpec(o,"configured_protocol","string");propertySpec(o,"reboot_required","boolean");o["apply_time"]="next_boot";o["choices"]="off,thread,zigbee";}

static void runtimeDescription(JsonObject o){propertySpec(o,"loaded","boolean");propertySpec(o,"fault","boolean");propertySpec(o,"memory_used","integer","byte");eventSpecs(o,{"started","stopped","fault","boot_failed","log"});runtimeContract(core,o);}
static void workerDescription(JsonObject o){workerAsyncDescription(o);propertySpec(o,"active","boolean");eventSpecs(o,{"completed","failed"});o["capacity"]=2;o["hardware_access"]="via_main_application";o["scheduling"]="background_preemptible";}
